From a87113142245ef8a109752f69aef3f25bf3b2fa7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:26:52 +0100
Subject: [PATCH] applets/digital-clock: let numeric dates wrap in vertical
 panels

Dates like 14/10/2024 or 2024-10-14 have no spaces, so in thin vertical
panels they could not wrap and were shrunk to a tiny font. On vertical
panels, allow line breaks after the separators between their numbers.

BUG: 494736
---
 applets/digital-clock/DigitalClock.qml | 7 ++++++-
 1 file changed, 6 insertions(+), 1 deletion(-)

diff --git a/applets/digital-clock/DigitalClock.qml b/applets/digital-clock/DigitalClock.qml
index 8c918109d0..8edc8497be 100644
--- a/applets/digital-clock/DigitalClock.qml
+++ b/applets/digital-clock/DigitalClock.qml
@@ -580,7 +580,12 @@ MouseArea {
         timeZoneLabel.text = timezoneString;

         if (Plasmoid.configuration.showDate) {
-            dateLabel.text = main.dateFormatter(clock.dateTime);
+            let dateString = main.dateFormatter(clock.dateTime);
+            if (Plasmoid.formFactor === PlasmaCore.Types.Vertical) {
+                // let numeric dates like 14/10/2024 wrap after their separators in thin panels
+                dateString = dateString.replace(/(\d[^\s\d]+)(?=\d)/g, "$1​");
+            }
+            dateLabel.text = dateString;
         } else {
             // clear it so it doesn't take space in the layout
             dateLabel.text = "";
-- 
